// Responsibility: Implements a sentient pusher that actively avoids the fastest coin to challenge the player. // Attachment Note: Attach to the Pusher GameObject. using UnityEngine; public class PusherMovement : MonoBehaviour { private void Update() { GameObject fastestCoin = FindFastestCoin(); if (fastestCoin != null) { Vector3 directionAway = (transform.position - fastestCoin.transform.position).normalized; directionAway.y = 0; transform.position += directionAway * Time.deltaTime * 2f; } } private GameObject FindFastestCoin() { GameObject[] coins = GameObject.FindGameObjectsWithTag("Coin"); GameObject fastest = null; float maxSpeed = 0f; foreach (var coin in coins) { float speed = coin.GetComponent<Rigidbody>().velocity.magnitude; if (speed > maxSpeed) { maxSpeed = speed; fastest = coin; } } return fastest; } }